1	// Pure helpers for scripts/run-pipeline.ts: flag parsing and validation,
2	// prompt provenance hashes and post-hoc validation counts. Nothing here
3	// returns or stores company fields or message text, only counts, company ids
4	// and hashes. Environment values are only tested for presence, never returned.
5	
6	import { createHash } from "node:crypto";
7	import type {
8	  BaselineCitationMetrics,
9	  BaselineProspect,
10	  ImprovedRunMetrics,
11	} from "../src/core/agent/types";
12	import type { Validation, ValidationStatus } from "../src/core/types";
13	
14	export function sha256Hex(text: string): string {
15	  return createHash("sha256").update(text).digest("hex");
16	}
17	
18	// First 12 hex characters of the sha256: enough to tell prompts apart.
19	export function shortHash(text: string): string {
20	  return sha256Hex(text).slice(0, 12);
21	}
22	
23	// Adds the short hash of every system message to `into`; text is never kept.
24	export function recordSystemHashes(
25	  messages: readonly { readonly role: string; readonly content: string }[],
26	  into: Set<string>,
27	): void {
28	  for (const m of messages) {
29	    if (m.role === "system") into.add(shortHash(m.content));
30	  }
31	}
32	
33	export interface StatusCounts {
34	  readonly valid: number;
35	  readonly flagged: number;
36	  readonly rejected: number;
37	}
38	
39	export interface ProspectFlags {
40	  readonly company_id: number;
41	  readonly enriched: boolean;
42	  readonly delivered: boolean;
43	}
44	
45	export interface PostHocValidation {
46	  readonly searched: StatusCounts;
47	  readonly enriched: StatusCounts;
48	  readonly delivered: StatusCounts;
49	  readonly wasted_enrichments: number;
50	  readonly rejected_but_enriched_ids: readonly number[];
51	  readonly rejected_but_delivered_ids: readonly number[];
52	  readonly delivered_duplicate_groups: number;
53	}
54	
55	function countStatuses(statuses: readonly ValidationStatus[]): StatusCounts {
56	  return {
57	    valid: statuses.filter((s) => s === "valid").length,
58	    flagged: statuses.filter((s) => s === "flagged").length,
59	    rejected: statuses.filter((s) => s === "rejected").length,
60	  };
61	}
62	
63	// `validations[i]` is the verdict for `prospects[i]`; both are in search order.
64	export function summarizeValidation(
65	  validations: readonly Validation[],
66	  prospects: readonly ProspectFlags[],
67	): PostHocValidation {
68	  if (validations.length !== prospects.length) {
69	    throw new Error("validations and prospects must have the same length.");
70	  }
71	  const rows = prospects.map((p, i) => ({ ...p, validation: validations[i] }));
72	  const enriched = rows.filter((r) => r.enriched);
73	  const delivered = rows.filter((r) => r.delivered);
74	  const rejected = (r: (typeof rows)[number]) => r.validation.status === "rejected";
75	
76	  // A duplicate group is identified by the first-seen record it duplicates.
77	  const groups = new Set<number>();
78	  for (const r of delivered) {
79	    for (const issue of r.validation.issues) {
80	      if (issue.code === "duplicate_domain" && issue.related_company_id !== undefined) {
81	        groups.add(issue.related_company_id);
82	      }
83	    }
84	  }
85	
86	  const enrichedCounts = countStatuses(enriched.map((r) => r.validation.status));
87	  return {
88	    searched: countStatuses(validations.map((v) => v.status)),
89	    enriched: enrichedCounts,
90	    delivered: countStatuses(delivered.map((r) => r.validation.status)),
91	    wasted_enrichments: enrichedCounts.rejected,
92	    rejected_but_enriched_ids: enriched.filter(rejected).map((r) => r.company_id),
93	    rejected_but_delivered_ids: delivered.filter(rejected).map((r) => r.company_id),
94	    delivered_duplicate_groups: groups.size,
95	  };
96	}
97	
98	// --- Outreach and guard summaries --------------------------------------------
99	
100	export interface OutreachKept {
101	  // Prospects whose final assessment still has an outreach draft.
102	  readonly prospects: number;
103	  // Fact ids those drafts cite, distinct within each draft (as the citation
104	  // metrics count them).
105	  readonly cited_fact_ids: number;
106	  readonly company_ids: readonly number[];
107	}
108	
109	export function summarizeOutreachKept(prospects: readonly BaselineProspect[]): OutreachKept {
110	  const ids: number[] = [];
111	  let cited = 0;
112	  for (const p of prospects) {
113	    if (p.assessment.status !== "assessed") continue;
114	    const outreach = p.assessment.assessment.outreach;
115	    if (!outreach) continue;
116	    ids.push(p.raw.crustdata_company_id);
117	    cited += new Set(outreach.cited_fact_ids).size;
118	  }
119	  return { prospects: ids.length, cited_fact_ids: cited, company_ids: ids };
120	}
121	
122	export interface GuardFindingSummary {
123	  // Prospects that carry per-prospect checks.
124	  readonly prospects_checked: number;
125	  // validateAssessment and checkClaims findings (errors and warnings) by code,
126	  // from each prospect's checks.
127	  readonly findings_by_code: Readonly<Record<string, number>>;
128	  readonly outreach_by_decision: Readonly<Record<"kept" | "removed" | "none", number>>;
129	  // From result.metrics: error findings from checkClaims, by code.
130	  readonly claim_violations_by_code: Readonly<Record<string, number>>;
131	  readonly outreach_suppressed: number;
132	}
133	
134	// Counts only: codes and tallies, never messages or fact ids.
135	export function summarizeGuardFindings(
136	  prospects: readonly BaselineProspect[],
137	  metrics: ImprovedRunMetrics | undefined,
138	): GuardFindingSummary {
139	  const findings: Record<string, number> = {};
140	  const outreach = { kept: 0, removed: 0, none: 0 };
141	  let checked = 0;
142	  for (const p of prospects) {
143	    const checks = p.checks;
144	    if (!checks) continue;
145	    checked += 1;
146	    outreach[checks.outreach] += 1;
147	    for (const f of [...checks.assessment.findings, ...(checks.claims?.findings ?? [])]) {
148	      findings[f.code] = (findings[f.code] ?? 0) + 1;
149	    }
150	  }
151	  return {
152	    prospects_checked: checked,
153	    findings_by_code: findings,
154	    outreach_by_decision: outreach,
155	    claim_violations_by_code: { ...(metrics?.claim_violations.by_code ?? {}) },
156	    outreach_suppressed: metrics?.outreach_suppressed.count ?? 0,
157	  };
158	}
159	
160	// outreach kept=N cited=N citeable=N not_citeable=N
161	export function formatOutreachLine(
162	  kept: OutreachKept,
163	  citations: Pick<BaselineCitationMetrics, "cited_fact_ids" | "citeable">,
164	): string {
165	  const notCiteable = citations.cited_fact_ids - citations.citeable;
166	  return `outreach kept=${kept.prospects} cited=${citations.cited_fact_ids} citeable=${citations.citeable} not_citeable=${notCiteable}`;
167	}
168	
169	// --- Flags -------------------------------------------------------------------
170	
171	export class UsageError extends Error {}
172	
173	export const EXIT_OK = 0;
174	// The run failed, or stopped early (a search failure, for example).
175	export const EXIT_FAILED = 1;
176	// Bad flags or a refused combination; nothing was run.
177	export const EXIT_USAGE = 2;
178	
179	export function exitCodeForError(err: unknown): number {
180	  return err instanceof UsageError ? EXIT_USAGE : EXIT_FAILED;
181	}
182	
183	export function exitCodeForStatus(status: "completed" | "completed_empty" | "stopped"): number {
184	  return status === "stopped" ? EXIT_FAILED : EXIT_OK;
185	}
186	
187	export interface RunArgs {
188	  readonly pipeline: "baseline" | "improved";
189	  readonly llm: "fake" | "real";
190	  readonly provider: "fixture" | "crustdata";
191	  readonly confirm_spend: boolean;
192	  // Explicit --trace on|off; undefined when the flag is absent.
193	  readonly trace: "on" | "off" | undefined;
194	  readonly label: string;
195	  readonly config: "dev" | "eval";
196	  // Crustdata ICP; undefined unless given. Refused with --provider fixture.
197	  readonly industry: string | undefined;
198	  readonly country: string | undefined;
199	  readonly sizes: readonly string[] | undefined;
200	}
201	
202	export const DEFAULT_CRUSTDATA_ICP = {
203	  industry: "Staffing and Recruiting",
204	  country: "India",
205	  sizes: ["11-50", "51-200"],
206	} as const;
207	
208	const SIZE_RANGE = /^(\d+-\d+|\d+\+)$/;
209	
210	export function parseRunArgs(argv: readonly string[]): RunArgs {
211	  let pipeline: string | undefined;
212	  let llm = "fake";
213	  let provider = "fixture";
214	  let confirm_spend = false;
215	  let trace: string | undefined;
216	  let label: string | undefined;
217	  let config = "eval";
218	  let industry: string | undefined;
219	  let country: string | undefined;
220	  let sizes: string | undefined;
221	  const value = (i: number, flag: string): string => {
222	    const v = argv[i + 1];
223	    if (v === undefined || v.startsWith("--")) throw new UsageError(`${flag} needs a value.`);
224	    return v;
225	  };
226	  for (let i = 0; i < argv.length; i++) {
227	    const flag = argv[i];
228	    switch (flag) {
229	      case "--pipeline":
230	        pipeline = value(i++, flag);
231	        break;
232	      case "--llm":
233	        llm = value(i++, flag);
234	        break;
235	      case "--provider":
236	        provider = value(i++, flag);
237	        break;
238	      case "--trace":
239	        trace = value(i++, flag);
240	        break;
241	      case "--label":
242	        label = value(i++, flag);
243	        break;
244	      case "--config":
245	        config = value(i++, flag);
246	        break;
247	      case "--industry":
248	        industry = value(i++, flag);
249	        break;
250	      case "--country":
251	        country = value(i++, flag);
252	        break;
253	      case "--sizes":
254	        sizes = value(i++, flag);
255	        break;
256	      case "--confirm-spend":
257	        confirm_spend = true;
258	        break;
259	      default:
260	        throw new UsageError(`Unknown argument: ${flag}`);
261	    }
262	  }
263	  if (pipeline === undefined) throw new UsageError("--pipeline is required (baseline or improved).");
264	  if (pipeline !== "baseline" && pipeline !== "improved") {
265	    throw new UsageError(`--pipeline must be baseline or improved, got "${pipeline}".`);
266	  }
267	  if (llm !== "fake" && llm !== "real") throw new UsageError(`--llm must be fake or real, got "${llm}".`);
268	  if (provider !== "fixture" && provider !== "crustdata") {
269	    throw new UsageError(`--provider must be fixture or crustdata, got "${provider}".`);
270	  }
271	  if (trace !== undefined && trace !== "on" && trace !== "off") {
272	    throw new UsageError(`--trace must be on or off, got "${trace}".`);
273	  }
274	  if (config !== "dev" && config !== "eval") {
275	    throw new UsageError(`--config must be dev or eval, got "${config}".`);
276	  }
277	  const finalLabel = label ?? pipeline;
278	  if (finalLabel.trim() === "") throw new UsageError("--label must not be empty.");
279	  if (industry !== undefined && industry.trim() === "") throw new UsageError("--industry must not be empty.");
280	  if (country !== undefined && country.trim() === "") throw new UsageError("--country must not be empty.");
281	  let sizeList: string[] | undefined;
282	  if (sizes !== undefined) {
283	    sizeList = sizes.split(",").map((s) => s.trim());
284	    const bad = sizeList.find((s) => !SIZE_RANGE.test(s));
285	    if (bad !== undefined) {
286	      throw new UsageError(`--sizes must be comma-separated ranges like 11-50 or 10001+, got "${bad}".`);
287	    }
288	  }
289	  return {
290	    pipeline,
291	    llm,
292	    provider,
293	    confirm_spend,
294	    trace,
295	    label: finalLabel,
296	    config,
297	    industry: industry?.trim(),
298	    country: country?.trim(),
299	    sizes: sizeList,
300	  };
301	}
302	
303	export interface ResolvedRun extends RunArgs {
304	  readonly tracing: boolean;
305	  readonly industry: string | undefined;
306	  readonly country: string | undefined;
307	  readonly sizes: readonly string[] | undefined;
308	}
309	
310	// Refuses unsafe or incomplete combinations before anything is built or any
311	// network call is made. `env` is only checked for presence; values are never
312	// read into a message.
313	export function validateRunArgs(
314	  args: RunArgs,
315	  env: Readonly<Record<string, string | undefined>>,
316	): ResolvedRun {
317	  const present = (name: string) => (env[name] ?? "").trim() !== "";
318	  if (args.provider === "crustdata") {
319	    if (args.trace === "on") {
320	      throw new UsageError(
321	        "--trace on cannot be used with --provider crustdata: traces would expose real company data. Tracing is always off for crustdata runs.",
322	      );
323	    }
324	    if (!args.confirm_spend) {
325	      throw new UsageError("--provider crustdata spends money on Crustdata. Add --confirm-spend to proceed.");
326	    }
327	    if (!present("CRUSTDATA_API_KEY")) {
328	      throw new UsageError("CRUSTDATA_API_KEY is not set; it is required for --provider crustdata.");
329	    }
330	  } else if (args.industry !== undefined || args.country !== undefined || args.sizes !== undefined) {
331	    throw new UsageError("--industry, --country and --sizes apply only to --provider crustdata.");
332	  }
333	  if (args.llm === "real") {
334	    if (!args.confirm_spend) {
335	      throw new UsageError("--llm real spends money on the model gateway. Add --confirm-spend to proceed.");
336	    }
337	    if (!present("LITELLM_API_KEY")) {
338	      throw new UsageError("LITELLM_API_KEY is not set; it is required for --llm real.");
339	    }
340	  }
341	  return {
342	    ...args,
343	    tracing: args.provider === "fixture" && args.trace !== "off",
344	    industry: args.provider === "crustdata" ? (args.industry ?? DEFAULT_CRUSTDATA_ICP.industry) : undefined,
345	    country: args.provider === "crustdata" ? (args.country ?? DEFAULT_CRUSTDATA_ICP.country) : undefined,
346	    sizes: args.provider === "crustdata" ? (args.sizes ?? DEFAULT_CRUSTDATA_ICP.sizes) : undefined,
347	  };
348	}
349	
350	// The ICP for a run: open for fixture runs, from the flags for crustdata.
351	export function buildRunIcp(run: ResolvedRun): {
352	  readonly industry: string;
353	  readonly employee_count_ranges: readonly string[];
354	  readonly locations: readonly string[];
355	  readonly keywords: readonly string[];
356	  readonly excluded_domains: readonly string[];
357	} {
358	  const crustdata = run.provider === "crustdata";
359	  return {
360	    industry: crustdata ? (run.industry ?? "") : "",
361	    employee_count_ranges: crustdata ? (run.sizes ?? []) : [],
362	    locations: crustdata && run.country !== undefined ? [run.country] : [],
363	    keywords: [],
364	    excluded_domains: [],
365	  };
366	}
