1	// Agent-local types for the baseline and improved pipelines. These are not
2	// part of the shared contract in src/core/types.ts. Both pipelines return
3	// the same PipelineResult; fields only the improved pipeline fills are
4	// optional, so the baseline result is unchanged.
5	
6	import type {
7	  BudgetSnapshot,
8	  CompanyProvider,
9	  ProviderErrorCategory,
10	  SearchFilters,
11	} from "../data/provider";
12	import type {
13	  AnyFact,
14	  Assessment,
15	  RawCompany,
16	  Run,
17	  RunConfig,
18	  RunStep,
19	  Validation,
20	} from "../types";
21	import type { LlmCallMeta, LlmClient, LlmErrorCategory } from "./llm";
22	import type { LlmCostBasis, LlmKeySpend } from "./llm-cost";
23	import type { PipelineTracer } from "./tracer";
24	
25	// What the user asked for. Built by the app from its form.
26	export interface IcpInput {
27	  // Free text; mapped to provider industry labels via autocomplete.
28	  readonly industry: string;
29	  // Provider range strings, e.g. "51-200". Empty means any size.
30	  readonly employee_count_ranges: readonly string[];
31	  // Countries. SearchFilters takes one, so only the first is searched.
32	  readonly locations: readonly string[];
33	  // Given to the model only; the provider has no keyword filter.
34	  readonly keywords: readonly string[];
35	  // Given to the model only; neither pipeline filters on them.
36	  readonly excluded_domains: readonly string[];
37	}
38	
39	// Which pipeline produced a result.
40	export type PipelineKind = "naive_baseline" | "improved";
41	
42	export type EnrichmentStatus =
43	  | "enriched" // returned by the enrich call
44	  | "not_returned" // requested, but missing from the response
45	  | "skipped_budget" // not requested, or refused, because of the enrichment cap
46	  | "skipped_no_linkedin" // no LinkedIn URL, so it cannot be enriched
47	  | "skipped_ineligible" // improved only: rejected by validation (incl. duplicates)
48	  | "failed"; // the enrich call failed
49	
50	export interface EnrichmentOutcome {
51	  readonly status: EnrichmentStatus;
52	  // Set when the enrich call returned an error.
53	  readonly error_category?: ProviderErrorCategory;
54	}
55	
56	export type CheckSeverity = "error" | "warning";
57	
58	export type CheckFindingCode =
59	  // validateAssessment
60	  | "fit_score_out_of_range"
61	  | "criterion_score_out_of_range"
62	  | "missing_criterion"
63	  | "unexpected_criterion"
64	  | "duplicate_criterion"
65	  | "unknown_fact_reference"
66	  | "uncertain_fact_reference"
67	  // checkClaims
68	  | "no_citations"
