89	}
90	
91	// What the improved pipeline's guardrails decided for one company.
92	export interface AssessmentChecks {
93	  readonly assessment: CheckResult;
94	  // Absent when the assessment failed validation or drafted no outreach.
95	  readonly claims?: CheckResult;
96	  // kept: outreach passed checkClaims. removed: it failed and was dropped
97	  // from the assessment. none: there was no usable outreach to check.
98	  readonly outreach: "kept" | "removed" | "none";
99	}
