101	export type AssessmentOutcome =
102	  | { readonly status: "assessed"; readonly assessment: Assessment }
103	  | {
104	      readonly status: "failed";
105	      // invalid_assessment: improved only; validateAssessment() found errors.
106	      readonly reason: "llm_error" | "malformed_output" | "truncated" | "invalid_assessment";
107	      readonly message: string;
