113	      // llm_stopped: an earlier call failed in a way every later call would
114	      // repeat (auth failure, or rate limiting after all retries).
115	      // rejected / duplicate: improved only; validation rejected the record
116	      // (duplicate when the reason was a duplicate_domain issue).
117	      readonly reason:
118	        | "llm_call_cap"
