207	// Plain JSON: no records, no Maps or Sets.
208	export interface ImprovedRunMetrics {
209	  // Rejected by validation for a reason other than being a duplicate.
210	  readonly rejected: IdCount;
211	  // Usable but suspicious (status "flagged" in the final validation).
212	  readonly flagged: IdCount;
213	  // Later duplicates removed (duplicate_domain), at search or after enrichment.
214	  readonly duplicates_removed: IdCount;
215	  readonly enrichment: {
216	    // Not rejected at search and has a LinkedIn URL. Ids in search order.
217	    readonly eligible: IdCount;
218	    // Sent to the enrich call, within the cap. Ids in the order sent:
219	    // "valid" companies first, then "flagged", each in search order.
220	    readonly requested: IdCount;
221	    // Returned by the enrich call. Ids in search order.
