249	  // missing (no such fact for that company), model_provider, uncertain,
250	  // other_non_citeable (any other status outside CITEABLE_FACT_STATUSES),
251	  // citeable.
252	  readonly citeable: number;
253	  readonly missing: number;
254	  // The part of `missing` that names another company's fact.
